// Чертёж (класс)
class User {
  // Конструктор — план того, как собрать объект
  constructor(name, age) {
    this.name = name;   // свойство name = то, что передали
    this.age = age;     // свойство age = то, что передали
  }

  // Метод — действие, которое умеет объект
  greet() {
    return `Hi, I'm ${this.name}`;
  }
}

// Постройка конкретного объекта (экземпляр)
const alice = new User("Alice", 25);
console.log(alice.name);   // Alice
console.log(alice.greet()); // Hi, I'm Alice

class Car {
  constructor(brand, year) {
    // this — это будущий объект, который создаётся
    this.brand = brand;  // сохраняем brand как свойство
    this.year = year;    // сохраняем year как свойство
    this.mileage = 0;    // можно задать значение по умолчанию
  }
}

const car1 = new Car("Toyota", 2020);
const car2 = new Car("BMW", 2023);

console.log(car1.brand);  // Toyota
console.log(car2.brand);  // BMW
console.log(car1.year);   // 2020

class Counter {
  constructor() {
    this.count = 0;  // у каждого экземпляра свой счётчик
  }

  increment() {
    this.count++;  // увеличиваю СВОЙ счётчик
    return this.count;
  }
}

const c1 = new Counter();
const c2 = new Counter();

c1.increment();  // this = c1
c1.increment();  // this = c1
c2.increment();  // this = c2

console.log(c1.count);  // 2 — c1 incremented twice
console.log(c2.count);  // 1 — c2 incremented once
// Каждый объект хранит данные НЕЗАВИСИМО!

class Point {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
}

// Правильно — с new:
const p1 = new Point(3, 4);  // this = новый объект { x:3, y:4 }
console.log(p1.x);            // 3

// Неправильно — без new:
// const p2 = Point(3, 4);   // TypeError!
// 'Class constructor Point cannot be invoked without new'

// new создаёт НОВЫЙ объект каждый раз:
const p3 = new Point(1, 2);
const p4 = new Point(1, 2);
console.log(p3 === p4);  // false — разные объекты!

