class BankAccount {
  constructor(owner, balance = 0) {
    this.owner = owner;
    this.balance = balance;
  }

  deposit(amount) {
    this.balance += amount;  // добавляем к балансу
    return this.balance;
  }

  withdraw(amount) {
    if (amount > this.balance) {
      return "Insufficient funds";  // проверяем достаточно ли
    }
    this.balance -= amount;
    return this.balance;
  }

  info() {
    return `${this.owner}: ${this.balance}`;
  }
}

const acc = new BankAccount("Alice", 100);
acc.deposit(50);     // баланс 150
acc.withdraw(200);   // "Insufficient funds"
console.log(acc.info());  // Alice: 150

class MathHelper {
  static add(a, b) {
    return a + b;  // this тут не нужен — это утилита
  }

  static PI = 3.14159;  // static поле
}

console.log(MathHelper.add(2, 3));  // 5 — вызов на классе
// const m = new MathHelper();
// m.add(2, 3);  // Ошибка! add не на экземпляре

class Timer {
  constructor() {
    this.seconds = 0;
  }

  tick() {
    this.seconds++;  // this.seconds — нужен this!
    console.log(this.seconds);
  }
}

const t = new Timer();

// БАГ: this потерян!
// setTimeout(t.tick, 100);  // TypeError: Cannot read 'seconds' of undefined

// РЕШЕНИЕ 1: стрелочная функция
setTimeout(() => t.tick(), 100);  // this = t (через замыкание)

// РЕШЕНИЕ 2: bind
setTimeout(t.tick.bind(t), 100);  // this = t (явная привязка)

class Animal {}
class Dog extends Animal {}

const d = new Dog();

console.log(d instanceof Dog);     // true — создан через Dog
console.log(d instanceof Animal);  // true — Dog наследует Animal
console.log(d instanceof Object);  // true — все объекты наследуют Object

class Person {
  constructor(first, last) {
    this.first = first;
    this.last = last;
  }

  // Геттер — вызывается при ЧТЕНИИ obj.fullName
  get fullName() {
    return `${this.first} ${this.last}`;
  }

  // Сеттер — вызывается при ЗАПИСИ obj.fullName = "..."
  set fullName(name) {
    const [f, l] = name.split(" ");
    this.first = f;
    this.last = l;
  }
}

const p = new Person("Alice", "Smith");
console.log(p.fullName);  // Alice Smith — как свойство, но это метод!
p.fullName = "Bob Jones";
console.log(p.first);     // Bob

class Account {
  #pin;  // приватное поле — снаружи недоступно

  constructor(pin) {
    this.#pin = pin;  // внутри класса доступ есть
  }

  checkPin(input) {
    return input === this.#pin;  // проверка внутри класса
  }
}

const acc = new Account(1234);
console.log(acc.checkPin(1234));  // true
// console.log(acc.#pin);          // SyntaxError!
// console.log(acc.pin);           // undefined — не существует снаружи

